async def _entry_detail(
    session: SessionDep, tenant_id: uuid.UUID, entry_id: uuid.UUID
) -> JournalEntryDetail:
    """Load an entry + its lines and validate into the detail schema. ``refresh`` materializes the
    server-side ``updated_at`` in the async context BEFORE the synchronous ``model_validate`` —
    otherwise validating a just-flushed object whose ``updated_at`` is expired triggers an async
    lazy-load in a sync serialization context (MissingGreenlet)."""
    entry, lines = await service.get_entry_with_lines(session, tenant_id, entry_id)
    await session.refresh(entry)
    detail = JournalEntryDetail.model_validate(entry)
    return detail.model_copy(
        update={"lines": [JournalLineRead.model_validate(line) for line in lines]}
    )

